def histogram(test):
    counts = {}
    for char in test.split():
        counts[char] = counts.get(char, 0) + 1
    if not counts:
        return {}
    max_count = max(counts.values())
    return {k: v for k, v in counts.items() if v == max_count}

def reverse_delete(s, c):
    result = ''.join(ch for ch in s if ch not in c)
    return result, result == result[::-1]

def prod_signs(arr):
    """
    You are given an array arr of integers and you need to return
    sum of magnitudes of integers multiplied by product of all signs
    of each number in the array, represented by 1, -1 or 0.
    Note: return None for empty arr.

    Example:
    >>> prod_signs([1, 2, 2, -4]) == -9
    >>> prod_signs([0, 1]) == 0
    >>> prod_signs([]) == None
    """
    if not arr:
        return None
    sign = 1
    for x in arr:
        if x > 0:
            continue
        elif x < 0:
            sign *= -1
        else:
            return 0
    return sign * sum(abs(x) for x in arr)

def greatest_common_divisor(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b
    >>> greatest_common_divisor(3, 5)
    1
    >>> greatest_common_divisor(25, 15)
    5
    """
    while b:
        a, b = b, a % b
    return abs(a)

def digits(n):
    product = 1
    has_odd = False
    for digit in str(n):
        d = int(digit)
        if d % 2 != 0:
            product *= d
            has_odd = True
    return product if has_odd else 0

def can_arrange(arr):
    for i in range(len(arr) - 1, 0, -1):
        if arr[i] < arr[i-1]:
            return i
    return -1

def do_algebra(operator, operand):
    expression = str(operand[0])
    for op, val in zip(operator, operand[1:]):
        expression += f" {op} {val}"
    return eval(expression)

def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    return sorted(set(l))

def prime_fib(n: int):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2 or num == 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    a, b = 0, 1
    count = 0
    while True:
        if is_prime(b):
            count += 1
            if count == n:
                return b
        a, b = b, a + b

def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    return s[n-shift:] + s[:n-shift]

def fruit_distribution(s, n):
    import re
    nums = re.findall(r'\d+', s)
    return n - int(nums[0]) - int(nums[1])

def triangle_area(a, b, c):
    if a + b <= c or a + c <= b or b + c <= a:
        return -1
    s = (a + b + c) / 2
    area = (s * (s - a) * (s - b) * (s - c)) ** 0.5
    return round(area, 2)

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    total_sum = sum(numbers)
    total_prod = 1
    for n in numbers:
        total_prod *= n
    return total_sum, total_prod

def prime_length(string):
    n = len(string)
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def encode(message):
    vowels = 'aeiouAEIOU'
    result = []
    for char in message:
        if char in vowels:
            result.append(chr(ord(char) + 2).swapcase())
        elif char.isalpha():
            result.append(char.swapcase())
        else:
            result.append(char)
    return ''.join(result)

def check_dict_case(dict):
    if not dict:
        return False
    return all(isinstance(k, str) and k.islower() for k in dict) or \
           all(isinstance(k, str) and k.isupper() for k in dict)
